/// `2^-53`, the unit roundoff of `f64`.
const UNIT: f64 = 1.1102230246251565e-16;

/// `2^-1074`, the smallest positive `f64`.
const TINY: f64 = 5e-324;

/// `fl(fl(a * b) + 2^-1074)` for non-negative `a` and `b`, or zero if either is
/// zero: at least `(1 - 2^-53)^2 * a * b`, also when `a * b` underflows, since
/// adding `2^-1074` to a value below `2^-1022` is exact.
#[inline]
fn covered_product(a: f64, b: f64) -> f64 {
    if a == 0.0 || b == 0.0 {
        0.0
    } else {
        a * b + TINY
    }
}

/// The bound on the rounding error of the sum or difference `s` of `x` and `y`:
/// the covered product of `2^-53` and `|s|`, or zero if an operand is zero,
/// when the operation is exact.
#[inline]
fn sum_rounding(x: f64, y: f64, s: f64) -> f64 {
    if x != 0.0 && y != 0.0 {
        covered_product(UNIT, s.abs())
    } else {
        0.0
    }
}

/// The bound on the rounding error of the product `p` of `x` and `y`: the
/// covered product of `2^-53` and `|p|`, plus `2^-1074` for underflow, or zero
/// if an operand is zero, when the operation is exact. The test is on the
/// operands: a product that underflows is zero without being exact.
#[inline]
fn product_rounding(x: f64, y: f64, p: f64) -> f64 {
    if x != 0.0 && y != 0.0 {
        covered_product(UNIT, p.abs()) + TINY
    } else {
        0.0
    }
}

/// The error bound stored for a coordinate whose value is `approx` and whose
/// computed error is `err`: `err * slack` rounded up, which is at least the
/// error since the slack factor covers the roundings of its computation; zero
/// when `err` is zero; and `+∞` when `approx` or the bound is not finite.
#[inline]
fn finish(approx: f64, err: f64, slack: f64) -> f64 {
    let bound = err * slack;
    if !(approx.is_finite() && bound.is_finite()) {
        f64::INFINITY
    } else if err == 0.0 {
        0.0
    } else {
        bound.next_up()
    }
}

/// `2^1020`: the expansions of the core require every operand of a sum to be
/// below it in magnitude.
const SUM_OPERAND_LIMIT: f64 = 1.1235582092889474e307;

/// Whether every component of `e` is below `SUM_OPERAND_LIMIT` in magnitude, as
/// the components of an operand of a sum of expansions must be.
#[inline]
fn summable(e: &[f64]) -> bool {
    e.iter().all(|x| x.abs() < SUM_OPERAND_LIMIT)
}

/// Whether every component of `e` lies in the product domain of the core, zero
/// or a magnitude from `2^-480` to `2^480`, as the components of an operand of
/// an exact product must.
#[inline]
fn multipliable(e: &[f64]) -> bool {
    e.iter().all(|&x| eft::in_product_domain(x))
}

/// The span of a coordinate just written, or the error of `write_exact` once
/// the arena is reset to `mark`: [`ExactError::OutOfRange`] when `in_range` is
/// false.
#[inline]
fn written(
    scratch: &mut Scratch<'_>,
    mark: Mark,
    span: Result<Span, ScratchExhausted>,
    in_range: bool,
) -> Result<Span, ExactError> {
    match span {
        Ok(span) if in_range => Ok(span),
        Ok(_) => {
            scratch.reset(mark);
            Err(ExactError::OutOfRange)
        }
        Err(e) => {
            scratch.reset(mark);
            Err(e.into())
        }
    }
}
